windowclass.script:
function onInit()
	onDiceChanged();
end
function onDiceChanged()
	local bShow = not dice.isEmpty();
	dice.setVisible(bShow);
	button_roll.setVisible(bShow);
end
function action(draginfo)
	local sLabel = name.getValue();
	local aDice = dice.getDice();
	local nMod = bonus.getValue();

	if dice.isEmpty() then
		if draginfo then
			draginfo.setType("number");
			draginfo.setDescription(sLabel);
			draginfo.setStringData(sLabel);
			draginfo.setNumberData(nMod);
		else
			ModifierStack.addSlot(sLabel, nMod);
		end
	else
			local rRoll = { sType = "dice", sDesc = name.getValue(), aDice = dice.getDice(), nMod = bonus.getValue() };
			ActionsManager.performAction(draginfo, nil, rRoll);
	end

	return true;
end
function onDrop(x, y, draginfo)
	local sDragType = draginfo.getType();
	if sDragType == "dice" then
		local aDropDice = draginfo.getDiceData();
		for _,vDie in ipairs(aDropDice) do
			dice.addDie(vDie.type);
		end
		return true;
	end
end

number_listitem_right.script:
function onDragStart(button, x, y, draginfo)
	return window.action(draginfo);
end

dice_listitem_right.script:
function onValueChanged()
	window.onDiceChanged();
end
function onDragStart(button, x, y, draginfo)
	return window.action(draginfo);
end

button_listitem_roll_right.script:
function onDragStart(button, x, y, draginfo)
	return window.action(draginfo);
end
function onButtonPress()
	return window.action();
end
